16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName",
23	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials",
25	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
26	            + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
27	    @Mapping(target = "membershipLevel",
28	        expression = "java(toMembershipLevel(owner))")
29	    @Mapping(target = "locality",
30	        expression = "java(toLocality(owner))")
31	    @Mapping(target = "contactPreference",
32	        expression = "java(toContactPreference(owner))")
33	    @Mapping(target = "identityKey",
34	        expression = "java(toIdentityKey(owner))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * Derive an owner's duplicate-detection identity key: the normalized E.164 telephone, the
39	     * lower-cased email (empty when none), and the household id (empty when none), joined with
40	     * {@code '|'}. Two owners are duplicates only when their whole identity keys are equal.
41	     *
42	     * <p>This is the single source of truth for the key: it is both returned on the DTO and used by
43	     * the create endpoint's 409 duplicate check, so the value clients see is exactly the value that
44	     * governs rejection. The "email present" rule reuses {@link #hasEmail(Owner)}.
45	     */
46	    default String toIdentityKey(Owner owner) {
47	        String email = hasEmail(owner) ? owner.getEmail() : "";
48	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
49	        return owner.getTelephone() + "|" + email + "|" + household;
50	    }
51	
52	    /**
53	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
54	     * for the "is an email present" rule shared by the derived fields below.
55	     */
56	    default boolean hasEmail(Owner owner) {
57	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
58	    }
59	
60	    /**
61	     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
62	     * otherwise 'PHONE'.
63	     */
64	    default String toContactPreference(Owner owner) {
65	        return hasEmail(owner) ? "EMAIL" : "PHONE";
66	    }
67	
68	    /**
69	     * Derive an owner's numeric membership level (1 to 3): start at 1; add 1 when an email address is
70	     * present; add 1 when the owner has no namesakes (namesakeCount is 0); capped at 3 (level 4 is
71	     * reserved for tenure).
72	     */
73	    default Integer toMembershipLevel(Owner owner) {
74	        int level = 1;
75	        if (hasEmail(owner)) {
76	            level++;
77	        }
78	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
79	        if (noNamesakes) {
80	            level++;
81	        }
82	        return Math.min(level, 3);
83	    }
84	
85	    /**
86	     * Fixed city-to-region table used to derive an owner's locality.
87	     */
88	    Map<String, String> CITY_REGION = Map.of(
89	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
90	
91	    /**
92	     * Derive an owner's locality (region) from the city using the fixed
93	     * {@link #CITY_REGION} table, returning 'UNKNOWN' when the city is not listed.
94	     */
95	    default String toLocality(Owner owner) {
96	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
97	    }
98	
99	    Owner toOwner(OwnerDto ownerDto);
100	
101	    @Mapping(target = "id", ignore = true)
102	    @Mapping(target = "pets", ignore = true)
103	    Owner toOwner(OwnerFieldsDto ownerDto);
104	
105	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
106	
107	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
108	
109	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
110	        OwnerPageDto ownerPageDto = new OwnerPageDto();
111	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
112	        ownerPageDto.setPage(ownerPage.getNumber());
113	        ownerPageDto.setSize(ownerPage.getSize());
114	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
115	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
116	        return ownerPageDto;
117	    }
118	}
